import * as T from '../../vendor/three.module.js';
// CPU triangle renderer for browsers without WebGL. Uses the same Three.js scene,
// geometry, perspective camera, movement and interactions as the GPU renderer.
export class SoftwareRenderer {
constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d',{alpha:false});if(!this.ctx)throw Error('Canvas 2D ไม่พร้อมใช้งาน');this.shadowMap={};this.cache=new WeakMap();this.last=0;this.width=1;this.height=1}
setPixelRatio(){}
setSize(w,h){if(this.width===w&&this.height===h)return;this.width=w;this.height=h;this.canvas.width=w;this.canvas.height=h}
render(scene,camera){const now=performance.now();if(now-this.last<65)return;this.last=now;scene.updateMatrixWorld();camera.updateMatrixWorld();const ctx=this.ctx,w=this.width,h=this.height;ctx.fillStyle='#d7e4d2';ctx.fillRect(0,0,w,h);const vp=new T.Matrix4().multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse),faces=[];const v=new T.Vector3();scene.traverse(o=>{if(!o.isMesh||!o.visible||o.material.opacity<.2)return;const geo=o.geometry;let cached=this.cache.get(geo);if(!cached){const p=geo.attributes.position,idx=geo.index;const tris=[];for(let i=0;i<(idx?idx.count:p.count);i+=3){const a=idx?idx.getX(i):i,b=idx?idx.getX(i+1):i+1,c=idx?idx.getX(i+2):i+2;const va=new T.Vector3().fromBufferAttribute(p,a),vb=new T.Vector3().fromBufferAttribute(p,b),vc=new T.Vector3().fromBufferAttribute(p,c);const normal=vb.sub(va).cross(vc.sub(va)).normalize();const shade=.78+Math.max(0,normal.dot(new T.Vector3(-.5,1,.7).normalize()))*.28;tris.push([a,b,c,shade])}cached={p,tris};this.cache.set(geo,cached)}const transform=new T.Matrix4().multiplyMatrices(vp,o.matrixWorld);const pts=[];for(let i=0;i<cached.p.count;i++){v.fromBufferAttribute(cached.p,i).applyMatrix4(transform);pts.push([(v.x+1)*w*.5,(1-v.y)*h*.5,v.z])}const base=o.material.color||new T.Color('#aabc8c');for(const [ia,ib,ic,s]of cached.tris){const a=pts[ia],b=pts[ib],c=pts[ic];if(a[2]>1||b[2]>1||c[2]>1||a[2]<-1||b[2]<-1||c[2]<-1)continue;const area=(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);if(area>=0)continue;if((a[0]<0&&b[0]<0&&c[0]<0)||(a[0]>w&&b[0]>w&&c[0]>w)||(a[1]<0&&b[1]<0&&c[1]<0)||(a[1]>h&&b[1]>h&&c[1]>h))continue;const col=base.clone().multiplyScalar(s);faces.push({a,b,c,layer:o.userData.groundLevel!==undefined?0:1,gy:o.userData.groundLevel||0,z:(a[2]+b[2]+c[2])/3,color:col.getStyle(),opacity:o.material.transparent?o.material.opacity:1})}});faces.sort((a,b)=>a.layer-b.layer||(a.layer===0?a.gy-b.gy:0)||b.z-a.z);for(const f of faces){ctx.globalAlpha=f.opacity;ctx.beginPath();ctx.moveTo(f.a[0],f.a[1]);ctx.lineTo(f.b[0],f.b[1]);ctx.lineTo(f.c[0],f.c[1]);ctx.closePath();ctx.fillStyle=f.color;ctx.fill();ctx.strokeStyle=f.color;ctx.lineWidth=.5;ctx.stroke()}ctx.globalAlpha=1}
}
